begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create schema tests;
create function tests.id(n integer) returns uuid language sql immutable as $$ select ('82000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
create function tests.h(n integer) returns text language sql immutable as $$ select lpad(to_hex(n),64,'a') $$;
create function tests.login(n integer) returns void language plpgsql as $$ begin
  perform set_config('request.jwt.claims',jsonb_build_object('sub',tests.id(n),'session_id',tests.id(200+n),'role','authenticated')::text,true);
end $$;
create function tests.dev(n integer) returns jsonb language sql immutable as $$ select jsonb_build_object('device',tests.id(500+n),'proof',tests.h(600+n),'code_hash',tests.h(700+n),'rate',tests.h(800+n),'browser','Test') $$;
create function tests.claim(n integer,tok integer) returns jsonb language sql as $$ select public.tv_pair_claim(jsonb_build_object('device',tests.id(500+n),'proof',tests.h(600+n),'rate',tests.h(800+n),'token_hash',tests.h(tok))) $$;
grant usage on schema tests to service_role,authenticated,anon;
grant execute on all functions in schema tests to service_role,authenticated,anon;
insert into churches(id,name,timezone) values(tests.id(20),'Church A','America/Toronto'),(tests.id(21),'Church B','America/Toronto');
insert into engagements(id,church_id,title,status) values(tests.id(10),tests.id(20),'Room A','pre_call'),(tests.id(11),tests.id(21),'Room B','pre_call');
insert into auth.users(id,email,email_confirmed_at) values(tests.id(1),'ann@example.org',now()),(tests.id(2),'fac@clearway.co',now()),(tests.id(3),'other@clearway.co',now());
insert into auth.identities(user_id,provider,provider_id,identity_data) select id,'google',id::text,jsonb_build_object('email',email,'email_verified',true) from auth.users where id in(tests.id(2),tests.id(3));
insert into auth.sessions(id,user_id) values(tests.id(201),tests.id(1)),(tests.id(202),tests.id(2)),(tests.id(203),tests.id(3));
insert into auth.mfa_amr_claims(id,session_id,created_at,updated_at,authentication_method) select gen_random_uuid(),id,now(),now(),case when user_id=tests.id(1) then 'otp' else 'oauth' end from auth.sessions;
insert into clearway_users(id,auth_user_id,name,email,team_hub_team_member_id) values(tests.id(302),tests.id(2),'Lead A','fac@clearway.co',tests.id(402)),(tests.id(303),tests.id(3),'Lead B','other@clearway.co',tests.id(403));
insert into engagement_facilitators(engagement_id,clearway_user_id,role) values(tests.id(10),tests.id(302),'lead'),(tests.id(11),tests.id(303),'lead');
select ok(not has_function_privilege('anon','public.tv_pair_link(uuid,text)','execute'),'Anyone not signed in cannot issue a link');
select ok(has_function_privilege('authenticated','public.tv_pair_link(uuid,text)','execute'),'A signed-in browser can ask to issue one');
select ok(not has_function_privilege('authenticated','public.tv_pair_claim(jsonb)','execute'),'A browser cannot claim a link itself');
select ok(not has_function_privilege('anon','public.tv_pair_claim(jsonb)','execute'),'Anyone not signed in cannot claim a link');
select ok(has_function_privilege('service_role','public.tv_pair_claim(jsonb)','execute'),'The app server claims links');
select ok(not has_table_privilege('authenticated','private.tv_pair_links','select'),'A browser cannot read the link table');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.tv_pair_links'::regclass),'Row level security is forced on the link table');
select is((select count(*)::int from pg_policies where schemaname='private' and tablename='tv_pair_links'),0,'The link table has no policy');
set local role authenticated;
select tests.login(1);
select is(public.tv_pair_link(tests.id(10),tests.h(1))->>'status','denied','A participant cannot issue a link');
select tests.login(3);
select is(public.tv_pair_link(tests.id(10),tests.h(1))->>'status','denied','A facilitator of another engagement cannot issue a link for this one');
select throws_ok($$select count(*) from private.tv_pair_links$$,'42501',null,'A facilitator cannot read the link table');
select tests.login(2);
select is(public.tv_pair_link(tests.id(10),'not-a-hash')->>'status','invalid_request','A link needs a hash');
select is((select r-'expires_at' from (select public.tv_pair_link(tests.id(10),tests.h(1)) r)x),'{"status":"ok","skin":"clearway"}'::jsonb,'The lead issues a link and learns the skin');
select is(public.tv_pair_link(tests.id(10),tests.h(1))->>'status','invalid_request','A hash cannot be issued twice');
select public.tv_pair_link(tests.id(10),tests.h(2));select public.tv_pair_link(tests.id(10),tests.h(3));select public.tv_pair_link(tests.id(10),tests.h(4));select public.tv_pair_link(tests.id(10),tests.h(5));
reset role;
select ok((select expires_at between now()+interval '299 seconds' and now()+interval '301 seconds' from private.tv_pair_links where token_hash=tests.h(1)),'A link lasts 5 minutes');
select is((select facilitator_id from private.tv_pair_links where token_hash=tests.h(1)),tests.id(302),'It is bound to the facilitator who asked');
select is((select engagement_id from private.tv_pair_links where token_hash=tests.h(1)),tests.id(10),'It is bound to the engagement');
-- Claims
select is((select status from (select public.tv_device('sync',tests.dev(1))->>'status' status)x),'pair','A new TV window starts as an unpaired TV');
select is(tests.claim(1,99)->>'status','invalid_link','An unknown link is refused');
select is((select engagement_id from private.tv_devices where id=tests.id(501)),null,'And pairs nothing');
select is(public.tv_pair_claim(jsonb_build_object('device',tests.id(501),'proof',tests.h(999),'rate',tests.h(801),'token_hash',tests.h(1)))->>'status','denied','The wrong device proof is refused');
select is(tests.claim(1,1)->>'status','paired','A good link pairs the window');
select is((select engagement_id from private.tv_devices where id=tests.id(501)),tests.id(10),'It is paired to the link''s engagement');
select is((select label from private.tv_devices where id=tests.id(501)),'This laptop','Named This laptop');
select ok((select code_hash is null and code_expires_at is null and paired_at is not null from private.tv_devices where id=tests.id(501)),'Its code is used up and the pairing time set');
select ok((select used_at is not null and device_id=tests.id(501) from private.tv_pair_links where token_hash=tests.h(1)),'The link is used');
select is(public.tv_device('sync',tests.dev(1))->>'status','approved','The usual exchange can now finish the pairing');
select is(tests.claim(1,1)->>'status','paired','The same window asking again at once stays paired');
select is((select count(*)::int from private.tv_devices where engagement_id=tests.id(10) and not deleted),1,'And is not paired twice');
select public.tv_device('sync',tests.dev(2));
select is(tests.claim(2,1)->>'status','invalid_link','A used link does not pair a different browser');
select is((select engagement_id from private.tv_devices where id=tests.id(502)),null,'That browser stays unpaired');
select is(tests.claim(2,2)->>'status','paired','A second link pairs a second window');
select is((select label from private.tv_devices where id=tests.id(502)),'This laptop 2','Named with the next free name');
select is((select count(*)::int from private.tv_limits where key='claim:'||tests.h(802)),1,'Claims are counted per address');
-- Expiry
select public.tv_device('sync',tests.dev(3));
update private.tv_pair_links set expires_at=now()-interval '1 second' where token_hash=tests.h(3);
select is(tests.claim(3,3)->>'status','invalid_link','An expired link is refused');
select is((select used_at from private.tv_pair_links where token_hash=tests.h(3)),null,'And is not used up');
-- Facilitator who can no longer pair a TV
delete from engagement_facilitators where engagement_id=tests.id(10) and clearway_user_id=tests.id(302);
select is(tests.claim(3,4)->>'status','invalid_link','A link from a facilitator who has left the engagement is refused');
insert into engagement_facilitators(engagement_id,clearway_user_id,role) values(tests.id(10),tests.id(302),'lead');
-- Closed engagement
update engagements set status='closed' where id=tests.id(11);
set local role authenticated;select tests.login(3);
select is(public.tv_pair_link(tests.id(11),tests.h(7))->>'status','closed','No link is issued for a closed engagement');
reset role;
-- Moving a window from one engagement to another
update engagements set status='pre_call' where id=tests.id(11);
set local role authenticated;select tests.login(3);select public.tv_pair_link(tests.id(11),tests.h(8));reset role;
select is(tests.claim(1,8)->>'status','paired','A window paired to one engagement moves to the one its new link names');
select is((select engagement_id from private.tv_devices where id=tests.id(501)),tests.id(11),'It is paired there');
select is((select count(*)::int from private.tv_devices where engagement_id=tests.id(10) and not deleted),1,'And no longer in the first');
-- Issue limit
set local role authenticated;select tests.login(2);
select public.tv_pair_link(tests.id(10),tests.h(20+n)) from generate_series(1,8) n;
select is(public.tv_pair_link(tests.id(10),tests.h(40))->>'status','limited','A facilitator can issue only so many links in five minutes');
reset role;
select * from finish();
rollback;
